-- ==============================================================================
-- DATABASE SCHEMA: KLEVER FRUIT (HỆ THỐNG BÁN TRÁI CÂY NHẬP KHẨU VÀ GIỎ QUÀ CAO CẤP)
-- Hỗ trợ MySQL 8 / MariaDB, utf8mb4_unicode_ci, Tiền tệ BIGINT (VNĐ)
-- ==============================================================================

CREATE DATABASE IF NOT EXISTS `klever_fruits_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `klever_fruits_db`;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. BẢNG USERS (Tài khoản người dùng: Khách hàng, Nhân viên, Quản trị viên)
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `phone` VARCHAR(20) NOT NULL UNIQUE,
  `email` VARCHAR(100) NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `full_name` VARCHAR(100) NOT NULL,
  `role` ENUM('customer', 'staff', 'admin') NOT NULL DEFAULT 'customer',
  `avatar` VARCHAR(255) NULL,
  `status` ENUM('active', 'blocked') NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_users_role` (`role`),
  INDEX `idx_users_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. HỒ SƠ KHÁCH HÀNG (Hạng thành viên & Điểm tích lũy)
DROP TABLE IF EXISTS `customer_profiles`;
CREATE TABLE `customer_profiles` (
  `user_id` INT PRIMARY KEY,
  `tier` ENUM('bronze', 'silver', 'gold', 'diamond') NOT NULL DEFAULT 'bronze',
  `points` INT NOT NULL DEFAULT 0,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. HỒ SƠ NHÂN VIÊN (Gắn với chi nhánh cửa hàng)
DROP TABLE IF EXISTS `staff_profiles`;
CREATE TABLE `staff_profiles` (
  `user_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `position` VARCHAR(100) NOT NULL DEFAULT 'Nhân viên bán hàng',
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  INDEX `idx_staff_store` (`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. SỔ ĐỊA CHỈ KHÁCH HÀNG
DROP TABLE IF EXISTS `addresses`;
CREATE TABLE `addresses` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `receiver` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `province` VARCHAR(100) NOT NULL,
  `district` VARCHAR(100) NOT NULL,
  `ward` VARCHAR(100) NOT NULL,
  `detail` VARCHAR(255) NOT NULL,
  `is_default` BOOLEAN NOT NULL DEFAULT FALSE,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  INDEX `idx_addresses_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. CỬA HÀNG (20+ Chi nhánh Klever Fruit Hà Nội & TP.HCM)
DROP TABLE IF EXISTS `stores`;
CREATE TABLE `stores` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `address` VARCHAR(255) NOT NULL,
  `district` VARCHAR(100) NOT NULL,
  `city` VARCHAR(100) NOT NULL DEFAULT 'Hà Nội',
  `lat` DECIMAL(10, 7) NOT NULL,
  `lng` DECIMAL(10, 7) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `open_hours` VARCHAR(100) NOT NULL DEFAULT '07:00 - 22:00',
  `ship_fee_rules` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  INDEX `idx_stores_city_district` (`city`, `district`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. DANH MỤC SẢN PHẨM
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `parent_id` INT NULL,
  `name` VARCHAR(100) NOT NULL,
  `slug` VARCHAR(100) NOT NULL UNIQUE,
  `sort` INT NOT NULL DEFAULT 0,
  FOREIGN KEY (`parent_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  INDEX `idx_categories_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. BỘ SƯU TẬP (Quà tặng, Dịp lễ, Đối tượng)
DROP TABLE IF EXISTS `collections`;
CREATE TABLE `collections` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `slug` VARCHAR(150) NOT NULL UNIQUE,
  `type` ENUM('occasion', 'recipient', 'product') NOT NULL DEFAULT 'product',
  `banner` VARCHAR(255) NULL,
  `start_at` DATETIME NULL,
  `end_at` DATETIME NULL,
  INDEX `idx_collections_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. SẢN PHẨM TRÁI CÂY & GIỎ QUÀ
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(200) NOT NULL UNIQUE,
  `description` TEXT NULL,
  `origin` VARCHAR(100) NOT NULL,
  `base_price` BIGINT NOT NULL,
  `compare_price` BIGINT NULL,
  `discount_percent` INT NOT NULL DEFAULT 0,
  `category_id` INT NOT NULL,
  `is_gift` BOOLEAN NOT NULL DEFAULT FALSE,
  `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  INDEX `idx_products_category` (`category_id`),
  INDEX `idx_products_slug` (`slug`),
  INDEX `idx_products_price` (`base_price`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 9. BIẾN THỂ SẢN PHẨM (Hộp 1kg, Giỏ size M/L/VIP, Trọng lượng)
DROP TABLE IF EXISTS `product_variants`;
CREATE TABLE `product_variants` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `product_id` INT NOT NULL,
  `label` VARCHAR(100) NOT NULL,
  `price` BIGINT NOT NULL,
  `sku` VARCHAR(50) NOT NULL UNIQUE,
  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  INDEX `idx_variants_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10. HÌNH ẢNH SẢN PHẨM
DROP TABLE IF EXISTS `product_images`;
CREATE TABLE `product_images` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `product_id` INT NOT NULL,
  `url` VARCHAR(255) NOT NULL,
  `sort` INT NOT NULL DEFAULT 0,
  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  INDEX `idx_images_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 11. LIÊN KẾT SẢN PHẨM VÀ BỘ SƯU TẬP
DROP TABLE IF EXISTS `product_collections`;
CREATE TABLE `product_collections` (
  `product_id` INT NOT NULL,
  `collection_id` INT NOT NULL,
  PRIMARY KEY (`product_id`, `collection_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`collection_id`) REFERENCES `collections` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 12. TỒN KHO TỦ MÁT BẢO QUẢN THEO CỬA HÀNG
DROP TABLE IF EXISTS `inventory`;
CREATE TABLE `inventory` (
  `store_id` INT NOT NULL,
  `variant_id` INT NOT NULL,
  `qty` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`store_id`, `variant_id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 13. GIỎ HÀNG (Hỗ trợ cả khách vãng lai và thành viên)
DROP TABLE IF EXISTS `carts`;
CREATE TABLE `carts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `session_id` VARCHAR(100) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_carts_user` (`user_id`),
  INDEX `idx_carts_session` (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 14. CHI TIẾT GIỎ HÀNG
DROP TABLE IF EXISTS `cart_items`;
CREATE TABLE `cart_items` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `cart_id` INT NOT NULL,
  `variant_id` INT NOT NULL,
  `qty` INT NOT NULL DEFAULT 1,
  FOREIGN KEY (`cart_id`) REFERENCES `carts` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 15. ĐƠN HÀNG
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(50) NOT NULL UNIQUE,
  `user_id` INT NULL,
  `store_id` INT NOT NULL,
  `receiver_name` VARCHAR(100) NOT NULL,
  `receiver_phone` VARCHAR(20) NOT NULL,
  `receiver_address` VARCHAR(255) NOT NULL,
  `receiver_district` VARCHAR(100) NULL,
  `receiver_city` VARCHAR(100) NULL,
  `delivery_type` ENUM('ship', 'pickup') NOT NULL DEFAULT 'ship',
  `delivery_date` DATE NOT NULL,
  `delivery_slot` VARCHAR(50) NOT NULL,
  `greeting_message` TEXT NULL,
  `ribbon_color` VARCHAR(50) DEFAULT 'Ruy-băng Tím Klever',
  `subtotal` BIGINT NOT NULL,
  `ship_fee` BIGINT NOT NULL DEFAULT 0,
  `discount` BIGINT NOT NULL DEFAULT 0,
  `total` BIGINT NOT NULL,
  `payment_method` ENUM('cod', 'vietqr', 'vnpay') NOT NULL DEFAULT 'cod',
  `payment_status` ENUM('unpaid', 'paid', 'refunded') NOT NULL DEFAULT 'unpaid',
  `status` ENUM('PENDING', 'CONFIRMED', 'PREPARING', 'READY', 'SHIPPING', 'COMPLETED', 'CANCELLED', 'RETURNED') NOT NULL DEFAULT 'PENDING',
  `vat_request` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`),
  INDEX `idx_orders_status` (`status`),
  INDEX `idx_orders_user` (`user_id`),
  INDEX `idx_orders_store` (`store_id`),
  INDEX `idx_orders_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 16. SẢN PHẨM TRONG ĐƠN HÀNG
DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `order_id` INT NOT NULL,
  `variant_id` INT NOT NULL,
  `product_name` VARCHAR(200) NOT NULL,
  `variant_label` VARCHAR(100) NOT NULL,
  `unit_price` BIGINT NOT NULL,
  `qty` INT NOT NULL,
  `total_price` BIGINT NOT NULL,
  FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 17. LỊCH SỬ TRẠNG THÁI ĐƠN HÀNG
DROP TABLE IF EXISTS `order_status_history`;
CREATE TABLE `order_status_history` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `order_id` INT NOT NULL,
  `status` ENUM('PENDING', 'CONFIRMED', 'PREPARING', 'READY', 'SHIPPING', 'COMPLETED', 'CANCELLED', 'RETURNED') NOT NULL,
  `note` VARCHAR(255) NULL,
  `by_user_id` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  INDEX `idx_history_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 18. YÊU CẦU ĐỔI TRẢ (Trong vòng 48h sau khi COMPLETED)
DROP TABLE IF EXISTS `return_requests`;
CREATE TABLE `return_requests` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `order_id` INT NOT NULL,
  `reason` TEXT NOT NULL,
  `images` JSON NULL,
  `status` ENUM('pending', 'approved', 'rejected') NOT NULL DEFAULT 'pending',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `decided_by` INT NULL,
  `decision_note` VARCHAR(255) NULL,
  FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  INDEX `idx_returns_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 19. MÃ GIẢM GIÁ (COUPONS)
DROP TABLE IF EXISTS `coupons`;
CREATE TABLE `coupons` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(50) NOT NULL UNIQUE,
  `type` ENUM('percent', 'fixed') NOT NULL,
  `value` BIGINT NOT NULL,
  `min_order` BIGINT NOT NULL DEFAULT 0,
  `max_uses` INT NOT NULL DEFAULT 100,
  `used` INT NOT NULL DEFAULT 0,
  `expires_at` DATETIME NOT NULL,
  INDEX `idx_coupons_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 20. GIFT CARDS
DROP TABLE IF EXISTS `gift_cards`;
CREATE TABLE `gift_cards` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(50) NOT NULL UNIQUE,
  `balance` BIGINT NOT NULL,
  `expires_at` DATETIME NOT NULL,
  `status` ENUM('active', 'used', 'expired') NOT NULL DEFAULT 'active',
  INDEX `idx_giftcards_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 21. BIẾN ĐỘNG ĐIỂM THƯỞNG (LOYALTY)
DROP TABLE IF EXISTS `loyalty_transactions`;
CREATE TABLE `loyalty_transactions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `order_id` INT NULL,
  `points` INT NOT NULL,
  `type` ENUM('earn', 'redeem', 'refund') NOT NULL,
  `description` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  INDEX `idx_loyalty_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 22. ĐÁNH GIÁ SẢN PHẨM (REVIEWS)
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `product_id` INT NOT NULL,
  `user_id` INT NOT NULL,
  `rating` INT NOT NULL,
  `comment` TEXT NOT NULL,
  `status` ENUM('pending', 'approved', 'hidden') NOT NULL DEFAULT 'approved',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  INDEX `idx_reviews_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 23. SẢN PHẨM YÊU THÍCH (WISHLIST)
DROP TABLE IF EXISTS `wishlists`;
CREATE TABLE `wishlists` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `unique_wishlist` (`user_id`, `product_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 24. NGÀY ĐẶC BIỆT CỦA KHÁCH HÀNG (SINH NHẬT, KỶ NIỆM)
DROP TABLE IF EXISTS `special_dates`;
CREATE TABLE `special_dates` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `title` VARCHAR(100) NOT NULL,
  `date` DATE NOT NULL,
  `reminder_days` INT NOT NULL DEFAULT 3,
  `note` VARCHAR(255) NULL,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 25. BÀI VIẾT & VIDEO (TIN TỨC, CẨM NANG SỐNG LÀNH)
DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `type` ENUM('news', 'video') NOT NULL DEFAULT 'news',
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL UNIQUE,
  `excerpt` TEXT NOT NULL,
  `content` TEXT NOT NULL,
  `cover` VARCHAR(255) NOT NULL,
  `video_url` VARCHAR(255) NULL,
  `published_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_articles_slug` (`slug`),
  INDEX `idx_articles_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 26. TIN TUYỂN DỤNG
DROP TABLE IF EXISTS `job_posts`;
CREATE TABLE `job_posts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(200) NOT NULL,
  `department` VARCHAR(100) NOT NULL,
  `location` VARCHAR(150) NOT NULL,
  `salary_range` VARCHAR(100) NOT NULL,
  `description` TEXT NOT NULL,
  `requirements` TEXT NOT NULL,
  `status` ENUM('open', 'closed') NOT NULL DEFAULT 'open',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 27. HỒ SƠ ỨNG TUYỂN
DROP TABLE IF EXISTS `job_applications`;
CREATE TABLE `job_applications` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `job_id` INT NOT NULL,
  `full_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(100) NOT NULL,
  `cv_url` VARCHAR(255) NULL,
  `note` TEXT NULL,
  `status` ENUM('received', 'reviewing', 'accepted', 'rejected') NOT NULL DEFAULT 'received',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`job_id`) REFERENCES `job_posts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 28. GÓP Ý & PHẢN HỒI KHÁCH HÀNG
DROP TABLE IF EXISTS `feedbacks`;
CREATE TABLE `feedbacks` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(100) NULL,
  `content` TEXT NOT NULL,
  `status` ENUM('open', 'in_progress', 'resolved') NOT NULL DEFAULT 'open',
  `assigned_to` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 29. BANNERS QUẢNG CÁO ĐỘNG (WEB & MOBILE HERO / MID / CATEGORY)
DROP TABLE IF EXISTS `banners`;
CREATE TABLE `banners` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(150) NOT NULL,
  `subtitle` VARCHAR(255) NULL,
  `image_url` VARCHAR(255) NOT NULL,
  `image_web` VARCHAR(255) NULL,
  `image_mobile` VARCHAR(255) NULL,
  `placement` ENUM('home_hero', 'home_mid', 'category_top') NOT NULL DEFAULT 'home_hero',
  `platform` ENUM('web', 'mobile', 'all') NOT NULL DEFAULT 'all',
  `link_url` VARCHAR(255) NULL,
  `link_type` ENUM('collection', 'product', 'article', 'url') NOT NULL DEFAULT 'url',
  `link_value` VARCHAR(255) NULL,
  `cta_label` VARCHAR(100) NULL DEFAULT 'Mua ngay',
  `sort` INT NOT NULL DEFAULT 0,
  `start_at` DATETIME NULL,
  `end_at` DATETIME NULL,
  `countdown_at` DATETIME NULL,
  `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_banners_placement` (`placement`),
  INDEX `idx_banners_platform` (`platform`),
  INDEX `idx_banners_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 30. LỊCH CA LÀM VIỆC NHÂN VIÊN
DROP TABLE IF EXISTS `shifts`;
CREATE TABLE `shifts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `staff_id` INT NOT NULL,
  `date` DATE NOT NULL,
  `shift_type` ENUM('morning', 'afternoon', 'full') NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`),
  FOREIGN KEY (`staff_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 31. CHẤM CÔNG NHÂN VIÊN (CHECK-IN / CHECK-OUT)
DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `staff_id` INT NOT NULL,
  `store_id` INT NOT NULL,
  `check_in` DATETIME NOT NULL,
  `check_out` DATETIME NULL,
  `status` ENUM('on_time', 'late', 'absent') NOT NULL DEFAULT 'on_time',
  `note` VARCHAR(255) NULL,
  FOREIGN KEY (`staff_id`) REFERENCES `users` (`id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 32. NHẬT KÝ HOẠT ĐỘNG HỆ THỐNG (AUDIT LOGS)
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `action` VARCHAR(100) NOT NULL,
  `entity` VARCHAR(50) NOT NULL,
  `entity_id` INT NULL,
  `details` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_audit_user` (`user_id`),
  INDEX `idx_audit_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 33. CẤU HÌNH HỆ THỐNG
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `key` VARCHAR(100) PRIMARY KEY,
  `value` JSON NOT NULL,
  `description` VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 34. THEO DÕI SỰ KIỆN BANNER (VIEW & CLICK TRACKING)
DROP TABLE IF EXISTS `banner_events`;
CREATE TABLE `banner_events` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `banner_id` INT NOT NULL,
  `event_type` ENUM('VIEW', 'CLICK') NOT NULL,
  `platform` ENUM('web', 'mobile') NOT NULL DEFAULT 'web',
  `session_id` VARCHAR(100) NULL,
  `user_id` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`banner_id`) REFERENCES `banners` (`id`) ON DELETE CASCADE,
  INDEX `idx_banner_events_banner` (`banner_id`),
  INDEX `idx_banner_events_type` (`event_type`),
  INDEX `idx_banner_events_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==============================================================================
-- VIEWS THỐNG KÊ DOANH THU
-- ==============================================================================

CREATE OR REPLACE VIEW `view_daily_revenue` AS
SELECT
  DATE(created_at) AS report_date,
  COUNT(id) AS total_orders,
  SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_orders,
  COALESCE(SUM(CASE WHEN status = 'COMPLETED' THEN total ELSE 0 END), 0) AS daily_revenue
FROM orders
GROUP BY DATE(created_at)
ORDER BY report_date DESC;

CREATE OR REPLACE VIEW `view_store_revenue` AS
SELECT
  s.id AS store_id,
  s.name AS store_name,
  s.city AS store_city,
  COUNT(o.id) AS total_orders,
  SUM(CASE WHEN o.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_orders,
  COALESCE(SUM(CASE WHEN o.status = 'COMPLETED' THEN o.total ELSE 0 END), 0) AS total_revenue
FROM stores s
LEFT JOIN orders o ON s.id = o.store_id
GROUP BY s.id, s.name, s.city
ORDER BY total_revenue DESC;

SET FOREIGN_KEY_CHECKS = 1;

-- === OPERATIONS_SCHEMA ===
DROP TABLE IF EXISTS `pos_requests`;
CREATE TABLE IF NOT EXISTS pos_requests (
      user_id INT NOT NULL, request_key VARCHAR(100) NOT NULL, payload_hash CHAR(64) NOT NULL,
      order_id INT NULL, PRIMARY KEY (user_id, request_key)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `receipt_jobs`;
CREATE TABLE IF NOT EXISTS receipt_jobs (
      id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, user_id INT NOT NULL,
      state ENUM('sending','submitted','unknown') NOT NULL DEFAULT 'sending',
      created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(order_id)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `payment_events`;
CREATE TABLE IF NOT EXISTS payment_events (
      id INT AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(20) NOT NULL, event_id VARCHAR(100) NOT NULL,
      order_id INT NULL, amount BIGINT NOT NULL, outcome VARCHAR(40) NOT NULL,
      created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY(provider,event_id)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `inventory_batches`;
CREATE TABLE IF NOT EXISTS inventory_batches (
      id INT AUTO_INCREMENT PRIMARY KEY, store_id INT NOT NULL, variant_id INT NOT NULL,
      batch_no VARCHAR(100) NOT NULL, qty INT NOT NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
      expires_at DATETIME NULL, legacy TINYINT(1) NOT NULL DEFAULT 0,
      UNIQUE KEY(store_id,variant_id,batch_no), INDEX(store_id,variant_id,received_at,id), INDEX(expires_at)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `batch_allocations`;
CREATE TABLE IF NOT EXISTS batch_allocations (
      id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, batch_id INT NOT NULL, qty INT NOT NULL,
      restored TINYINT(1) NOT NULL DEFAULT 0, INDEX(order_id)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `push_devices`;
CREATE TABLE IF NOT EXISTS push_devices (
      token VARCHAR(255) PRIMARY KEY, user_id INT NOT NULL, platform VARCHAR(20) NOT NULL,
      updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `operation_jobs`;
CREATE TABLE IF NOT EXISTS operation_jobs (
      id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(30) NOT NULL, dedupe_key VARCHAR(160) NOT NULL,
      payload JSON NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0,
      available_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, locked_at DATETIME NULL, last_error VARCHAR(500) NULL,
      UNIQUE KEY(kind,dedupe_key), INDEX(state,available_at)) ENGINE=InnoDB;

DROP TABLE IF EXISTS `shipments`;
CREATE TABLE IF NOT EXISTS shipments (
      order_id INT PRIMARY KEY, provider VARCHAR(30) NOT NULL, tracking_number VARCHAR(100) NOT NULL,
      provider_id VARCHAR(100) NULL, state VARCHAR(30) NOT NULL, tracking_url TEXT NULL) ENGINE=InnoDB;

DROP TABLE IF EXISTS `delivery_quotes`;
CREATE TABLE IF NOT EXISTS delivery_quotes (
      id VARCHAR(64) PRIMARY KEY, store_id INT NOT NULL, address VARCHAR(500) NOT NULL,
      lat DECIMAL(10,7) NOT NULL, lng DECIMAL(10,7) NOT NULL, fee BIGINT NOT NULL,
      provider VARCHAR(30) NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB;

DROP TABLE IF EXISTS `order_deliveries`;
CREATE TABLE IF NOT EXISTS order_deliveries (
      order_id INT PRIMARY KEY, quote_id VARCHAR(64) NOT NULL, lat DECIMAL(10,7) NOT NULL,
      lng DECIMAL(10,7) NOT NULL, address VARCHAR(500) NOT NULL) ENGINE=InnoDB;

DROP TABLE IF EXISTS `verified_reviews`;
CREATE TABLE IF NOT EXISTS verified_reviews (
      review_id INT PRIMARY KEY, order_id INT NOT NULL, user_id INT NOT NULL, product_id INT NOT NULL,
      UNIQUE KEY(user_id,product_id,order_id)) ENGINE=InnoDB;

